package dev.kubejseditor.recipe.compat;

import com.google.gson.*;
import java.util.*;
import static dev.kubejseditor.recipe.compat.CompatDefinition.*;

/** Exact semantic profiles supplement schema metadata, not field-name heuristics. */
public final class CompatDefinitions {
    public static boolean isRitual(String type){return Set.of("forbidden_arcanus:ritual","forbidden_arcanus:hephaestus_forge/ritual").contains(type);}
    public static CompatDefinition machine(String type){var d=new CompatDefinition(type,"modern_industrialization");for(String key:List.of("item_inputs","fluid_inputs","item_outputs","fluid_outputs")){var f=d.add("/"+key,key.contains("fluid")?"流体"+(key.endsWith("inputs")?"输入":"输出"):"物品"+(key.endsWith("inputs")?"输入":"输出"),key.contains("fluid")?Kind.FLUID:Kind.ITEM,key.endsWith("inputs")?Role.INPUT:Role.OUTPUT);f.list=true;f.quantity="amount";f.probability="probability";f.unit=f.kind==Kind.FLUID?"mB":"个";}
        number(d,"/eu","配方耗电","EU/t",1,true);number(d,"/duration","加工时间","tick",200,true);d.add("/process_conditions","加工条件",Kind.JSON,Role.CONDITION);return d;}
    public static CompatDefinition ritual(JsonObject data){var d=new CompatDefinition("forbidden_arcanus:ritual","forbidden_arcanus");var f=d.add("/inputs","外围基座",Kind.ITEM,Role.INPUT);f.list=true;f.expand="amount";
        d.add("/main_ingredient","中央原料",Kind.ITEM,Role.CENTER).required=true;
        var result=CompatJson.get(data,"/result/type");String type=result.isJsonPrimitive()?result.getAsString():"";
        if(type.equals("forbidden_arcanus:create_item")){var out=d.add("/result/result_item","产物",Kind.ITEM,Role.OUTPUT);out.quantity="count";out.required=true;}
        else if(type.equals("forbidden_arcanus:transmute_input")){d.add("/result/result_item","转化目标（继承原组件）",Kind.ITEM,Role.OUTPUT).required=true;}
        else if(type.equals("forbidden_arcanus:upgrade_tier")){var level=number(d,"/result/result_tier","升级后的锻台等级","级",2,true);level.role=Role.RESULT;level.required=true;}
        else throw new IllegalArgumentException("未适配的仪式结果类型："+type);
        var enhancers=d.add("/enhancers","增强器要求（非消耗原料）",Kind.ITEM,Role.CATALYST);enhancers.registry="forbidden_arcanus:enhancer";enhancers.list=CompatJson.get(data,"/enhancers").isJsonArray();
        for(String key:List.of("aureal","souls","blood","experience")){var n=number(d,"/essences/"+key,Map.of("aureal","灵气","souls","灵魂","blood","血液","experience","经验").get(key),"",0,true);n.role=Role.RESOURCE;}
        number(d,"/forge_tier","锻台等级要求","级",1,true);var exact=d.add("/match_tier_exact","必须精确匹配等级",Kind.BOOLEAN,Role.CONDITION);exact.fallback=new JsonPrimitive(false);number(d,"/duration","仪式时间","tick",500,true);d.add("/magic_circle","仪式法阵",Kind.STRING,Role.PARAMETER);return d;}
    public static CompatDefinition apparatus(String type){var d=new CompatDefinition(type,"ars_nouveau");var f=d.add("/pedestalItems","外围原料",Kind.ITEM,Role.INPUT);f.list=true;d.add("/reagent","中央原料",Kind.ITEM,Role.CENTER).required=true;var out=d.add("/result","产物",Kind.ITEM,Role.OUTPUT);out.quantity="count";out.required=true;number(d,"/sourceCost","魔源需求","Source",0,true).role=Role.RESOURCE;var keep=d.add("/keepNbtOfReagent","保留中央原料组件",Kind.BOOLEAN,Role.CONDITION);keep.fallback=new JsonPrimitive(false);return d;}
    public static Field number(CompatDefinition d,String path,String label,String unit,long fallback,boolean integer){var f=d.add(path,label,Kind.NUMBER,Role.PARAMETER);f.fallback=new JsonPrimitive(fallback);f.integer=integer;f.unit=unit;return f;}
    public static CompatDefinition jdteInfusion(String type){var d=new CompatDefinition(type,"jdte-infusion");d.add("/input","物品输入",Kind.ITEM,Role.INPUT).quantity="count";d.add("/fluid","流体输入",Kind.FLUID,Role.INPUT).quantity="amount";d.add("/output","产物",Kind.ITEM,Role.OUTPUT).quantity="count";number(d,"/energy","配方能量","FE",0,true);return d;}
    public static CompatDefinition jdteBioFactory(String type,JsonObject data){var d=new CompatDefinition(type,"jdte-bio-factory");d.add("/specimen","标本要求",Kind.ITEM,Role.CATALYST).required=true;var inputs=CompatJson.get(data,"/inputs");if(inputs.isJsonArray())for(int i=0;i<inputs.getAsJsonArray().size();i++){var v=inputs.getAsJsonArray().get(i).getAsJsonObject();boolean consumed=!v.has("count")||v.get("count").getAsInt()>0;var f=d.add("/inputs/"+i,consumed?"消耗原料":"原料要求（不消耗）",Kind.ITEM,consumed?Role.INPUT:Role.CATALYST);f.quantity=consumed?"count":"";f.displayQuantity=false;f.required=true;}var out=d.add("/outputs","产物",Kind.ITEM,Role.OUTPUT);out.list=true;out.quantity="count";out.probability="chance";number(d,"/process_ticks","加工时间","tick",600,true);number(d,"/energy","每轮配方能量","FE",1000,true);for(String direction:List.of("process","output")){if(data.has(direction+"_fluid"))d.add("/"+direction+"_fluid",direction.equals("process")?"加工流体 ID":"产物流体 ID",Kind.STRING,Role.PARAMETER);if(data.has(direction+"_fluid_amount"))number(d,"/"+direction+"_fluid_amount",direction.equals("process")?"加工流体数量":"产物流体数量","mB",0,true);}return d;}
    public static CompatDefinition current(CompatDefinition saved,JsonObject data){var current=!saved.automatic()?saved:saved.source.equals("forbidden_arcanus")?ritual(data):saved.source.equals("jdte-bio-factory")?jdteBioFactory(saved.type,data):saved;current.type=saved.type;current.modVersion=saved.modVersion;current.shape=saved.shape;current.autoDiscover=saved.autoDiscover;return current;}
    public static void switchRitualResult(JsonObject data,String type){var r=new JsonObject();r.addProperty("type",type);switch(type){case "forbidden_arcanus:create_item" -> {var item=new JsonObject();item.addProperty("id","minecraft:diamond");item.addProperty("count",1);r.add("result_item",item);}case "forbidden_arcanus:transmute_input" -> r.addProperty("result_item","minecraft:diamond");case "forbidden_arcanus:upgrade_tier" -> r.addProperty("result_tier",2);default -> throw new IllegalArgumentException("未知结果类型");}data.add("result",r);}
    private CompatDefinitions(){}
}
